scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV_AWS_136'] || []

control 'CKV_AWS_136' do
  title 'Ensure that ECR repositories are encrypted using KMS'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_ecr_repository resources that actually exist, enumerated through
    the declarative API spec.
  DESC

  desc 'rationale', <<~RATIONALE
    The default AES256 encryption uses a key the account does not control;
    KMS makes the key auditable and revocable.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: aws_ecr_repository:
    encryption_configuration/[0]/encryption_type is KMS
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_ecr_repository:

      resource "aws_ecr_repository" "example" {
        encryption_configuration {
          encryption_type = "KMS"
          kms_key         = aws_kms_key.ecr.arn
        }
      }

    Out of band — aws_ecr_repository:

      Set at creation; encryption configuration cannot be changed on an existing repository.
  FIX

  tag checkov_id:            'CKV_AWS_136'
  tag checkov_category:      'ENCRYPTION'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'value'
  tag tf_resources:          %w[aws_ecr_repository]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/ecr_repository#encryption-configuration'
  tag nist:                  ['SC-28', 'SC-28 (1)']
  tag nist_r4:               ['SC-28', 'SC-28 (1)']
  tag cci:                   ['CCI-001199', 'CCI-002475']
  tag ksi:                   ['KSI-SVC-CER']
  tag severity:              'medium'
  tag severity_source:       'assessed'
  tag nist_source:           'reviewed'
  tag implementation_status: 'implemented'

  assets = aws_api_assets(type: 'aws_ecr_repository', regions: scan_regions)

  # A field the API did not return is nil, and nil is not a failing value:
  # the asset does not express this setting, so it is out of scope for this
  # check rather than in breach of it.
  in_scope = assets.assets(exempt: exempt)
                   .reject { |a| a[:encryption_type].nil? }

  applicable = !in_scope.empty?
  impact 0.5
  impact 0.0 unless applicable
  only_if('no aws_ecr_repository in scope expressing this setting') { applicable }

  in_scope.each do |asset|
    describe "aws_ecr_repository #{asset[:id]} (#{asset[:account_id]}/#{asset[:region]})" do
      subject { asset[:encryption_type] }
      it { should eq 'KMS' }
    end
  end
end
